import{_ as f,C as s,o as k,c as y,j as t,a,E as o,a8 as _}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/iK9gmxXyBR0-640.webp",A="/schedule-dashboard/thumbs/yt/iK9gmxXyBR0-1280.webp",r="/schedule-dashboard/thumbs/yt/hFNbPmzzcEs-640.webp",x="/schedule-dashboard/thumbs/yt/hFNbPmzzcEs-1280.webp",i="/schedule-dashboard/thumbs/yt/DxP5aW4VknQ-640.webp",P="/schedule-dashboard/thumbs/yt/DxP5aW4VknQ-1280.webp",l="/schedule-dashboard/thumbs/yt/fTUinMqA1XQ-640.webp",T="/schedule-dashboard/thumbs/yt/fTUinMqA1XQ-1280.webp",h="/schedule-dashboard/thumbs/yt/3Krz7Rdd4JI-640.webp",N="/schedule-dashboard/thumbs/yt/3Krz7Rdd4JI-1280.webp",c="/schedule-dashboard/thumbs/yt/gbeuC0ud1p4-640.webp",I="/schedule-dashboard/thumbs/yt/gbeuC0ud1p4-1280.webp",d="/schedule-dashboard/thumbs/yt/vg3JdjGuJwM-640.webp",R="/schedule-dashboard/thumbs/yt/vg3JdjGuJwM-1280.webp",p="/schedule-dashboard/thumbs/yt/rS36lYuvXQ8-640.webp",C="/schedule-dashboard/thumbs/yt/rS36lYuvXQ8-1280.webp",u="/schedule-dashboard/thumbs/yt/_NBx2NNOuA4-640.webp",S="/schedule-dashboard/thumbs/yt/_NBx2NNOuA4-1280.webp",w="/schedule-dashboard/thumbs/yt/_7P580m4kPY-640.webp",q="/schedule-dashboard/thumbs/yt/_7P580m4kPY-1280.webp",m="/schedule-dashboard/thumbs/yt/TlOAhw9t5DA-640.webp",M="/schedule-dashboard/thumbs/yt/TlOAhw9t5DA-1280.webp",g="/schedule-dashboard/thumbs/yt/ktbAVYsAxpk-640.webp",z="/schedule-dashboard/thumbs/yt/ktbAVYsAxpk-1280.webp",ae=JSON.parse('{"title":"AI Digest · Wed 11 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-11","routine":"digest"},"relativePath":"digest/2026-11-11.md","filePath":"digest/[date].md"}'),D={name:"digest/2026-11-11.md"},B=n+" 640w, "+A+" 1280w",Y=r+" 640w, "+x+" 1280w",E=i+" 640w, "+P+" 1280w",V=l+" 640w, "+T+" 1280w",O=h+" 640w, "+N+" 1280w",J=c+" 640w, "+I+" 1280w",Q=d+" 640w, "+R+" 1280w",W=p+" 640w, "+C+" 1280w",K=u+" 640w, "+S+" 1280w",X=w+" 640w, "+q+" 1280w",L=m+" 640w, "+M+" 1280w",j=g+" 640w, "+z+" 1280w",F={id:"ai-digest-·-wed-11-nov-2026",tabindex:"-1"};function G(H,e,U,Z,$,ee){const b=s("Badge"),v=s("DayFilter");return k(),y("div",null,[t("h1",F,[e[0]||(e[0]=a("AI Digest · Wed 11 Nov 2026 ",-1)),o(b,{type:"tip",text:"12"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-wed-11-nov-2026","aria-label":'Permalink to "AI Digest · Wed 11 Nov 2026 <Badge type="tip" text="12" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 11 Nov 2026 · run date Wed 11 Nov 2026 · 12 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(` 12 new talks in the last 24 hours. The newest are Ara Khan's (Cline) talk on picking problems that will survive the next model (11 Nov, 5:30 AM IST) and Raymond Weitekamp's talk on agents that don't need an LLM for every decision (4:30 AM IST). Most worth watching: Girish Konda (Microsoft) on treating sub-agents as a distributed system, Ayush Bhardwaj on mining 20,000 tool calls to fix his CLI for agents, Zenity's sandboxed scan of agent skills that found about 100 malicious ones, and Harvey's lessons from its internal agent platform. Only Vorflux's "Merge Is the Bottleneck" is mostly a repeat: its first half is the usual cloud coding-agent setup, and merging gets about 30 seconds.`)]),t("p",null,[t("strong",null,"Better Stack:"),a(" no new videos in the last 24 hours.")])],-1)),o(v),e[5]||(e[5]=_('<div class="grid cards2"><article class="it full" id="v-iK9gmxXyBR0" data-title="Pick Problems That Survive When AI Solves Coding - Ara Khan, Cline" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=iK9gmxXyBR0" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+B+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=iK9gmxXyBR0" target="_blank" rel="noopener">Pick Problems That Survive When AI Solves Coding - Ara Khan, Cline</a></h3><div class="meta">AI Engineer · Ara Khan, founding engineer at Cline · uploaded 11 Nov, 5:30 AM IST · 26:49</div><div class="verdict v-skim"><b>Verdict:</b> skim from 12:02 — the 17-hour harness loop and the career framing are the substance. The first 12 minutes are a history of AI and basic eval setup, and no before/after numbers are given for the loop.</div><div class="repeat">🔁 Repeat: &#39;self-improving agents&#39; — seen 24 times before. New here: an overnight loop where one model tuned Cline&#39;s harness for another model&#39;s Terminal Bench score, plus career advice built on the idea.</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 36 times before. New here: the specific harness faults the loop found (agents going in circles, background processes running too long, file index issues).</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 67 times before. New here: little; the Terminal Bench setup (89 tasks in 89 sandboxed containers) is background for the loop.</div><div class="sh">A harness that improves itself</div><ul><li><strong>The gap that started it:</strong> Cline with Kimi K3 scored 77.5% on Terminal Bench 2.1, while the model&#39;s release paper claimed 85% or more, so the team wanted to automate the slow work of tuning the harness by hand (<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=199s" target="_blank" rel="noopener">3:19</a>–<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=291s" target="_blank" rel="noopener">4:51</a>)</li><li><strong>How the eval runs (repeat):</strong> Each of Terminal Bench 2.1&#39;s 89 tasks runs in its own sandboxed container in parallel. Graders check turns, tokens, latency, tool calls and cheating, and failures get sorted into buckets such as a broken read-file tool or slow inference hitting the 45-minute limit (<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=568s" target="_blank" rel="noopener">9:28</a>–<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=692s" target="_blank" rel="noopener">11:32</a>)</li><li><strong>The 17-hour loop:</strong> GPT 5.6 ran Kimi K3 through the eval, read the failures, edited Cline&#39;s harness and reran it on its own for 17 hours. It found loop detection problems, background processes running too long and file index issues. No final score is given. He thinks this works across a broad set of problems but is much harder in real time, because the loop over-fits to specific problems (<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=722s" target="_blank" rel="noopener">12:02</a>–<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=878s" target="_blank" rel="noopener">14:38</a>)</li></ul><div class="sh">The loop beyond the harness</div><ul><li><strong>Kernels and inference:</strong> He cites an OpenAI post saying GPT 5.6 rewrote its own production kernels, cutting end-to-end serving cost by 20% and raising token generation efficiency by 15%. He also says a kernel competition winner had never hand-written a GPU operator. His point is that every stage can be optimized by agents, from pre-training data and post-training to evals and inference (<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=878s" target="_blank" rel="noopener">14:38</a>–<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=1032s" target="_blank" rel="noopener">17:12</a>)</li><li><strong>Every human correction marks a gap:</strong> When you have to fix a model&#39;s cache setup by hand, that correction shows where the model falls short, which is what post-training targets. Anything with a checkable result can be optimized, including physical things (<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=1063s" target="_blank" rel="noopener">17:43</a>–<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=1155s" target="_blank" rel="noopener">19:15</a>)</li><li><strong>A gadget tuned overnight:</strong> He gave a coding agent an OpenRouter key and a slow camera-speaker-mic device. The agent sent it tasks, measured end-to-end latency, and adjusted the firmware, tool calls, inference model and speech-to-text model through overnight experiments (<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=1186s" target="_blank" rel="noopener">19:46</a>–<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=1276s" target="_blank" rel="noopener">21:16</a>)</li></ul><div class="sh">Career advice</div><ul><li><strong>Move closer to the self-improvement loop:</strong> Vertical &quot;AI agents for construction&quot;-style products miss the bigger picture and may be one model release away from being wiped out. Work on things where models fall short instead: inference, post-training, physical interaction, hardware, networking (<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=1307s" target="_blank" rel="noopener">21:47</a>–<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=1429s" target="_blank" rel="noopener">23:49</a>)</li><li><strong>Choosing problems:</strong> Pick ambitious, focused, fast projects that gain from bigger models but can&#39;t be solved by scale alone, and ideally feed back into the improvement pipeline, such as data pipelines or physical hardware (<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=1459s" target="_blank" rel="noopener">24:19</a>–<a href="https://www.youtube.com/watch?v=iK9gmxXyBR0&amp;t=1550s" target="_blank" rel="noopener">25:50</a>)</li></ul></div></article><article class="it full" id="v-hFNbPmzzcEs" data-title="Your Agent Doesn&#39;t Need an LLM for Every Decision - Raymond Weitekamp, OpenProse" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=hFNbPmzzcEs" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+Y+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=hFNbPmzzcEs" target="_blank" rel="noopener">Your Agent Doesn&#39;t Need an LLM for Every Decision - Raymond Weitekamp, OpenProse</a></h3><div class="meta">AI Engineer · Raymond Weitekamp, OpenProse · uploaded 11 Nov, 4:30 AM IST · 51:48</div><div class="verdict v-skim"><b>Verdict:</b> skim from 12:29 — the RDM rules, the Factorio demo and the map/arbiter design are new and interesting. The first 12 minutes cover naming, and the 37–44 min section is personal history and the laptop orchestra.</div><div class="repeat">🔁 Repeat: &#39;decision models&#39; — seen 9 times before. New here: Recursive Decision Models (RDM), where a decision model sits at the root and calls more decisions, with generation as an optional extra.</div><div class="repeat">🔁 Repeat: &#39;computer-use agents&#39; — seen 6 times before. New here: oSo, a voice-first computer-use agent built on decision models rather than an LLM (waitlist only).</div><div class="sh">What a recursive decision model is</div><ul><li><strong>Decision models balance generation:</strong> System one or decision models such as Jev can only rank and pick from given options, never write text. That makes them converge, while LLMs diverge. The question he keeps asking: what if a lot of &quot;reasoning&quot; is really many tiny, fast decisions? (<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=279s" target="_blank" rel="noopener">4:39</a>–<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=439s" target="_blank" rel="noopener">7:19</a>)</li><li><strong>The recursive language model pattern, applied to decisions:</strong> Like recursive language models from MIT, a root can call sub-models up to a maximum depth. Using Jev as a tool inside a coding agent (compaction, tool-call gating, routing) is the obvious case. His interest is the reverse: a decision model at the root that may choose to call an LLM (<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=439s" target="_blank" rel="noopener">7:19</a>–<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=591s" target="_blank" rel="noopener">9:51</a>)</li><li><strong>Jev plays Doom:</strong> Two coupled sets of decisions, one for moment-to-moment combat and one map-aware set for exploring, made a Doom-playing agent from pure Jev calls. He calls it widely seen but rarely built on (<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=591s" target="_blank" rel="noopener">9:51</a>–<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=749s" target="_blank" rel="noopener">12:29</a>)</li><li><strong>Three rules:</strong> Context stays outside the model so code can cut it into slices. A decision can call another decision. It must work with no generative model at all, yet still combine with LLMs and agents (<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=779s" target="_blank" rel="noopener">12:59</a>–<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=902s" target="_blank" rel="noopener">15:02</a>)</li></ul><div class="sh">Demos</div><ul><li><strong>Search without the beam:</strong> For Typesafe&#39;s search over 12,000 Shopify product categories, each layer simply picks which sub-category to explore next (e.g. for &quot;laptop backpack&quot;) instead of loading every category at once. Community demos zoom into images the same way by repeatedly cutting them in half (<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=1030s" target="_blank" rel="noopener">17:10</a>–<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=1250s" target="_blank" rel="noopener">20:50</a>)</li><li><strong>Factorio with no LLM:</strong> An RDM finds the broken production line, then the faulty inserter, and walks over to replace it, with nothing generative involved (it does take the long way round). When every possible action can be listed, as in games, browsers and much of computer use, decisions alone may be enough (<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=1282s" target="_blank" rel="noopener">21:22</a>–<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=1533s" target="_blank" rel="noopener">25:33</a>)</li><li><strong>Smart home, the &quot;map&quot; and the arbiter:</strong> When a decision isn&#39;t enough, the request goes to an LLM. The two share a &quot;map&quot; of named actions (e.g. TV on), and the LLM can add entries such as &quot;movie time = TV on + lights off&quot;. An arbiter acts like a write lock: many cheap decision models run in parallel and guess ahead, but the arbiter only lets one through to change state once it is confident. Available as a DSPy module and a Rust crate (<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=1689s" target="_blank" rel="noopener">28:09</a>–<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=2195s" target="_blank" rel="noopener">36:35</a>)</li></ul><div class="sh">Operating System One</div><ul><li><strong>Earshot demo:</strong> A tiny ChAI (ChucK AI) model reads 40–100 ms slices of audio. A teacher model trains it on the fly, and an RDM decides when to trust it. Switching workspaces by spoken number speeds up to about 45 ms by the end. This builds on his Princeton Laptop Orchestra work with real-time machine learning from about 18 years ago (<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=2626s" target="_blank" rel="noopener">43:46</a>–<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=2811s" target="_blank" rel="noopener">46:51</a>)</li><li><strong>oSo preview:</strong> A voice-first computer-use agent at oso.computer, waitlist only, so you can use a computer without touching it. It starts with decisions, hands jobs to Claude Code or Codex, learns your preferences, and moves decisions to the smallest model it has learned to trust (<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=2901s" target="_blank" rel="noopener">48:21</a>–<a href="https://www.youtube.com/watch?v=hFNbPmzzcEs&amp;t=3054s" target="_blank" rel="noopener">50:54</a>)</li></ul></div></article><article class="it full" id="v-DxP5aW4VknQ" data-title="Your Sub-Agents Are a Distributed System. Treat Them Like One. - Girish Konda, Microsoft" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=DxP5aW4VknQ" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+E+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=DxP5aW4VknQ" target="_blank" rel="noopener">Your Sub-Agents Are a Distributed System. Treat Them Like One. - Girish Konda, Microsoft</a></h3><div class="meta">AI Engineer · Girish Konda, principal software engineer at Microsoft (personal views; author of open-source MCP Pacemaker) · uploaded 11 Nov, 3:30 AM IST · 23:01</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a tight, concrete map from distributed-systems theory to sub-agent bugs, with real fixes from his MCP bridge and honest limits.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 24 times before. New here: sub-agent hand-offs treated as distributed-systems failures (partial failure, dirty reads, unbounded fan-out, retries), with a named consistency model.</div><div class="repeat">🔁 Repeat: &#39;MCP servers&#39; — seen 40 times before. New here: concrete bugs and fixes from his MCP Pacemaker bridge (timeouts, cold-start gates, session caps).</div><div class="repeat">🔁 Repeat: &#39;agent reliability&#39; — seen 8 times before. New here: &quot;timeout means unknown&quot; and &quot;submitted is not confirmed&quot; as rules you enforce in code.</div><div class="sh">The failures you inherit</div><ul><li><strong>Same old failures, new shape:</strong> An orchestrator, parallel workers, shared state that changes (memory files, repo, vector stores) and merged results make up a classic distributed system. A half-finished sub-agent returns success-looking text, workers read each other&#39;s guesses, the orchestrator never sees 429s or 503s, and a retry reruns side effects (<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=91s" target="_blank" rel="noopener">1:31</a>–<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=182s" target="_blank" rel="noopener">3:02</a>)</li><li><strong>Fluent but half done:</strong> In his example, three alerts were all labeled benign with the same confidence. One was checked against telemetry, one matched a title the agent had seen before, and one got no work at all. The orchestrator sees the conclusion, not the work behind it (<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=214s" target="_blank" rel="noopener">3:34</a>–<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=305s" target="_blank" rel="noopener">5:05</a>)</li><li><strong>A timeout is a suspicion:</strong> Citing the FLP (1985) and Chandra–Toueg (1996) papers, a worker that is still running looks the same as one whose reply was lost. In MCP Pacemaker, a server downloading itself on first run hit the 30-second timeout and looked dead, so it got its own initialize timeout. A crash during a call had its exit code overwritten by the timeout, so timeouts are now recorded only while the process is alive (<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=305s" target="_blank" rel="noopener">5:05</a>–<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=397s" target="_blank" rel="noopener">6:37</a>)</li><li><strong>Dirty reads and fake quorums:</strong> One sub-agent&#39;s guessed &quot;error rate fell 80%&quot; gets picked up by two others, so three agreeing outputs are really one unsupported claim counted three times. Real quorums work because read and write sets overlap, but three readers of the same shared context aren&#39;t independent (<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=458s" target="_blank" rel="noopener">7:38</a>–<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=549s" target="_blank" rel="noopener">9:09</a>)</li></ul><div class="sh">SAFE hand-offs</div><ul><li><strong>S, source facts:</strong> Every fact carries its source, version, scope, and when the data was current, read and used. With a 5-minute freshness limit, a decision at 9:07 on data read at 9:06 passes, and one at 9:15 is rejected and needs a fresh read. An observation has a source and a read time; an inference has neither (<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=701s" target="_blank" rel="noopener">11:41</a>–<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=796s" target="_blank" rel="noopener">13:16</a>)</li><li><strong>A, at-most-once effects:</strong> A lost reply after a tool opens a PR leads to a retry and a second PR. MCP&#39;s idempotent hint is only a hint and defaults to false. His fixes: give every side effect an identity, tie approval to that exact action and allow it once, read the result back (&quot;submitted is not confirmed&quot;), mark unanswered calls as possibly run, and treat approvals like fencing tokens checked at the gate rather than remembered in the prompt (<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=796s" target="_blank" rel="noopener">13:16</a>–<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=1011s" target="_blank" rel="noopener">16:51</a>)</li><li><strong>F, fan-out budgets:</strong> Parallel cold starts through npx broke the shared npm cache with lock errors. A gate now allows two at a time with a 15-second wait cap, and a session cap queues new sessions for 10 seconds and then refuses them, counted as a failure. Capacity has to be reserved before the start to avoid a check-then-act race. MCP&#39;s own example sends a rate limit back as a plain sentence the orchestrator code may never read (<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=1011s" target="_blank" rel="noopener">16:51</a>–<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=1106s" target="_blank" rel="noopener">18:26</a>)</li><li><strong>E, explicit outcomes:</strong> Every hand-off ends in a named state (stale, unknown, partial), and the orchestrator checks schema, evidence, freshness and recomputed numbers in code. &quot;10 errors in 1,000 requests&quot; versus &quot;6 in 600&quot; is the same 1% rate, so the claim that errors fell is refused (<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=1106s" target="_blank" rel="noopener">18:26</a>–<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=1198s" target="_blank" rel="noopener">19:58</a>)</li></ul><div class="sh">Limits</div><ul><li><strong>Costs and where it doesn&#39;t fit:</strong> It doesn&#39;t make facts true, deliver exactly once, or roll anything back (you design compensation steps), and it gives no global order. Writes favour consistency over availability, and every freshness check is another read. It&#39;s overkill for drafts a person reads first and doesn&#39;t fit setups with several orchestrators or peer agents (<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=1198s" target="_blank" rel="noopener">19:58</a>–<a href="https://www.youtube.com/watch?v=DxP5aW4VknQ&amp;t=1290s" target="_blank" rel="noopener">21:30</a>)</li></ul></div></article><article class="it full" id="v-fTUinMqA1XQ" data-title="Your Team&#39;s Agents Are All Shipping to the Same Code at Once - Patrick Debois, Tessl" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=fTUinMqA1XQ" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+V+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=fTUinMqA1XQ" target="_blank" rel="noopener">Your Team&#39;s Agents Are All Shipping to the Same Code at Once - Patrick Debois, Tessl</a></h3><div class="meta">AI Engineer · Patrick Debois, Tessl · uploaded 11 Nov, 2:30 AM IST · 22:50</div><div class="verdict v-skim"><b>Verdict:</b> skim — a useful checklist of patterns for many agents working on one codebase (intent conflicts and speculative merge trains are the freshest), but it&#39;s a survey without numbers or a worked case.</div><div class="repeat">🔁 Repeat: &#39;software factory&#39; — seen 20 times before. New here: the &quot;multiplayer&quot; angle, with many people and their agents on one main branch and one shared board.</div><div class="repeat">🔁 Repeat: &#39;merge queues / CI&#39; — seen 9 times before. New here: conflicts in intent rather than in lines of code, and speculative merge trains.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 42 times before. New here: little; review based on risk and human review only for exceptions are familiar.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 78 times before. New here: a list of concurrency patterns rather than a production case study.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 24 times before. New here: agents claiming tickets and announcing the files they will touch, and agents waiting, requeuing or re-planning when they collide.</div><div class="sh">One main branch for the agents</div><ul><li><strong>What breaks:</strong> A multiplayer factory brings about 10x more PRs, agents undoing each other&#39;s changes, every merge forcing other PRs to rebase and rerun tests (slower, costlier CI), plus agent incidents and factory upkeep (skills, loops) waiting for approval. His proposal: move from continuous delivery to &quot;concurrent delivery&quot; (<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=122s" target="_blank" rel="noopener">2:02</a>–<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=245s" target="_blank" rel="noopener">4:05</a>)</li><li><strong>Split, claim, isolate:</strong> Split work by area (auth vs payments), using the code&#39;s syntax tree down to the file or function. Agents claim tickets and announce which files they will touch. Each agent gets its own worktree, machine, mocked APIs, database snapshot and digital twins (<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=245s" target="_blank" rel="noopener">4:05</a>–<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=369s" target="_blank" rel="noopener">6:09</a>)</li><li><strong>Smarter collisions and merges:</strong> When agents collide they can wait, requeue or re-plan the work between them. Merges can work by function, have agents fix them, and adjust ahead of time for changes they see coming (<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=369s" target="_blank" rel="noopener">6:09</a>–<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=461s" target="_blank" rel="noopener">7:41</a>)</li><li><strong>Conflicts of intent:</strong> One PR switches invoice totals to cents while another changes reporting. Both merge cleanly and tests pass, but the report now shows the wrong units, so agents should check that intent still holds across merges. Speculative merge trains test PRs in compatible pairs, so one failing PR doesn&#39;t stall the rest (<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=461s" target="_blank" rel="noopener">7:41</a>–<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=554s" target="_blank" rel="noopener">9:14</a>)</li></ul><div class="sh">One board for the people</div><ul><li><strong>Agents in the team chat:</strong> Pulling an agent into a conversation lets it refine the ticket from several people&#39;s input and ask about tests and requirements, so the ticket becomes a shared plan. At Tessl, sales, marketing and support use the same pipeline, skills and loops to start features that engineering then reviews (<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=616s" target="_blank" rel="noopener">10:16</a>–<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=771s" target="_blank" rel="noopener">12:51</a>)</li><li><strong>Handing off to a human and logging decisions:</strong> Helix ML&#39;s idea: a stuck agent opens an IDE with its exact context, a human sorts it out and hands it back. Agents should offer options to choose from rather than open questions, and every decision goes into a shared log that people and agents can search (<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=771s" target="_blank" rel="noopener">12:51</a>–<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=896s" target="_blank" rel="noopener">14:56</a>)</li><li><strong>Review by risk (repeat):</strong> Keep PRs small enough for a human to read, ask agents for screenshots, videos and test proof, and decide how much human review a change needs from its impact: documentation can go straight through, auth gets human review, other changes roll out gradually. Plan for cheap restores and rollbacks (<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=896s" target="_blank" rel="noopener">14:56</a>–<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=1085s" target="_blank" rel="noopener">18:05</a>)</li><li><strong>Keeping people informed and the factory team:</strong> Non-engineers need changes explained in their own terms. Automate what you can and send exceptions to humans. A new &quot;factory team&quot;, like a platform team, owns skills, context and factory monitoring. Next up are personal agents that answer and decide on your behalf on the board (<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=1085s" target="_blank" rel="noopener">18:05</a>–<a href="https://www.youtube.com/watch?v=fTUinMqA1XQ&amp;t=1239s" target="_blank" rel="noopener">20:39</a>)</li></ul></div></article><article class="it full" id="v-3Krz7Rdd4JI" data-title="Every Company Is Building Agents That Can&#39;t Work Together - Justin Schroeder, Standard Agents" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=3Krz7Rdd4JI" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+O+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI" target="_blank" rel="noopener">Every Company Is Building Agents That Can&#39;t Work Together - Justin Schroeder, Standard Agents</a></h3><div class="meta">AI Engineer · Justin Schroeder, Standard Agents · uploaded 11 Nov, 1:30 AM IST · 34:49</div><div class="verdict v-skim"><b>Verdict:</b> skim from 13:17 — the spec tour and demo are concrete, but the first 13 minutes argue a case most viewers already accept, and it&#39;s a launch pitch for the speaker&#39;s own spec.</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 36 times before. New here: a proposed open spec for the agent harness itself, so agents built by different teams run in any compatible runtime.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 24 times before. New here: composition through sub-agents as tools and &quot;parent hooks&quot; that let an installed child agent wire itself into its parent without extra prompting.</div><div class="repeat">🔁 Repeat: &#39;vendor lock-in&#39; — seen 6 times before. New here: the spec argues agents should be vendor-agnostic in hosting but pinned to one specific model, quant and provider.</div><div class="repeat">🔁 Repeat: &#39;JS/TS ecosystem&#39; — seen 14 times before. New here: TypeScript is chosen as the one agent language because it runs everywhere and needs no build step.</div><div class="sh">Why companies still build their own agents</div><ul><li><strong>Integration, trust, efficacy:</strong> A business is its processes (an HVAC firm&#39;s warranty claims, crew scheduling, permits), so handing them to one general do-anything assistant with MCP plus markdown skills is too risky. &quot;If an agent can do anything, it might do anything&quot;, so each agent should only get the tools for its job, like looking up equipment and submitting a claim (<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=78s" target="_blank" rel="noopener">1:18</a>–<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=345s" target="_blank" rel="noopener">5:45</a>)</li><li><strong>Small agents win on narrow jobs:</strong> A single-task agent on a cheap model (DeepSeek V4.1 Flash) can be evaluated tightly, so tuning to the benchmark becomes a good thing. He cites the GEPA paper&#39;s finding that tuning an agent&#39;s prompt beats fine-tuning the model: &quot;a Gmail agent beats a Gmail skill&quot; (<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=349s" target="_blank" rel="noopener">5:49</a>–<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=535s" target="_blank" rel="noopener">8:55</a>)</li><li><strong>But every team&#39;s agent is a one-off:</strong> Loop orchestration, parallel tool calls and durability make every agent a custom harness. Two custom harnesses can&#39;t be shared or combined, and MCP tools that need inference end up rebuilding agents inside MCP. MCP, skills, AGENTS.md, A2A, ACP and x402 are all standardized, but the runtime isn&#39;t (<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=535s" target="_blank" rel="noopener">8:55</a>–<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=797s" target="_blank" rel="noopener">13:17</a>)</li></ul><div class="sh">The Standard Agent Specification (announced today, open source)</div><ul><li><strong>Definition and principles:</strong> Agents are &quot;deterministic software that harness the non-deterministic results produced by models&quot;. The principles are vendor-agnostic, domain-specific, tied to one model, composable and portable. You pin a specific model, quant and provider with stronger fallbacks, because some weak models are great at one thing (one Tencent model made 3D zen gardens cheaply) (<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=797s" target="_blank" rel="noopener">13:17</a>–<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=1170s" target="_blank" rel="noopener">19:30</a>)</li><li><strong>Everything is TypeScript code:</strong> Agents are packages (model, prompt, tools, sub-agents, rules, hooks, effects, thread) written in TypeScript. It runs everywhere and needs no build step, so agents can write and run agents and ship them as npm packages with no MCP server (<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=931s" target="_blank" rel="noopener">15:31</a>–<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=1170s" target="_blank" rel="noopener">19:30</a>)</li><li><strong>Building blocks:</strong> A tool can be a function, a sub-prompt (e.g. a one-off image generation) or a whole sub-agent. Both sides of a conversation can be AI, which gives built-in QA (a reviewer side catching a watermark), or deterministic handler code. Parent hooks let an installed child agent expose itself to its parent automatically, and effects are scheduled code such as reminders (<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=1170s" target="_blank" rel="noopener">19:30</a>–<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=1505s" target="_blank" rel="noopener">25:05</a>)</li><li><strong>Threads and runtime contract:</strong> Each thread is a sandbox with its own messages, KV store, file system and optional code execution with allow-listed imports. Threads can expose HTTP/WebSocket endpoints and use decision models. The spec defines behaviour, not implementation: their runtime runs on Cloudflare Durable Objects, where &quot;read file&quot; actually reads a database (<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=1505s" target="_blank" rel="noopener">25:05</a>–<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=1699s" target="_blank" rel="noopener">28:19</a>)</li></ul><div class="sh">Builder and demo</div><ul><li><strong>Standard Agent Builder:</strong> This is the first public runtime, which they have already used in production, including a coding agent made of many tiny sub-agents. In the demo, Claude Code turned a battery-warranty PDF into an agent in 5:21. The agent runs on DeepSeek V4.1 Flash with only process tools (check battery, offer trade-in, report safety issue, escalate to lead), and the admin view showed per-call cost, tokens and a 94% cache hit rate. The same agent ran as a website chatbot and could be exposed as an MCP server (<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=1733s" target="_blank" rel="noopener">28:53</a>–<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=1995s" target="_blank" rel="noopener">33:15</a>)</li><li><strong>Ask:</strong> Build runtimes in any language that can run the spec&#39;s TypeScript, publish agents, and help break the spec. He compares it to the early web&#39;s browser standards (<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=1995s" target="_blank" rel="noopener">33:15</a>–<a href="https://www.youtube.com/watch?v=3Krz7Rdd4JI&amp;t=2087s" target="_blank" rel="noopener">34:47</a>)</li></ul></div></article><article class="it full" id="v-gbeuC0ud1p4" data-title="Your PR Says the Tests Passed. Prove It. - Stephen Chin &amp; Cassandra Chin" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=gbeuC0ud1p4" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+J+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=gbeuC0ud1p4" target="_blank" rel="noopener">Your PR Says the Tests Passed. Prove It. - Stephen Chin &amp; Cassandra Chin</a></h3><div class="meta">AI Engineer · Stephen Chin, Neo4j &amp; Cassandra Chin, Tracetoon creator · uploaded 10 Nov, 11:27 PM IST · 23:01</div><div class="verdict v-skim"><b>Verdict:</b> skim from 9:10 — the failed &quot;tests passed&quot; example and the strong-writer/cheap-reviewer split are useful, but much of the talk is comic storytelling, and the benchmark gains (+2 to +4 points) are small and self-run.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 36 times before. New here: checking the claims in a PR description (such as &quot;tests passed&quot;) against the commands that actually ran, not checking the code.</div><div class="repeat">🔁 Repeat: &#39;token costs / AI spend&#39; — seen 26 times before. New here: a graph that pre-builds the evidence instead of making agents search session logs again and again, which cut tokens about in half.</div><div class="repeat">🔁 Repeat: &#39;knowledge graphs&#39; — seen 9 times before. New here: Relate, a new embedded in-memory graph database written in Rust that needs no LLM calls.</div><div class="repeat">🔁 Repeat: &#39;LLM-as-a-judge&#39; — seen 19 times before. New here: PR Bench scores PR descriptions with LLM judges checked by a human.</div><div class="sh">The problem with AI-written PRs</div><ul><li><strong>PRs rejected for what they say, not the code:</strong> Cassandra built Tracetoon (open source, with optional explainer comics) because many AI-era PRs get rejected for wrong or poorly written descriptions. A writer working from its own session log keeps compressing its context and gets less accurate, and usually just explains the diff line by line (<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=12s" target="_blank" rel="noopener">0:12</a>–<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=48s" target="_blank" rel="noopener">0:48</a>) (<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=275s" target="_blank" rel="noopener">4:35</a>–<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=408s" target="_blank" rel="noopener">6:48</a>)</li><li><strong>Recovering evidence across sessions:</strong> Tracetoon reads the agent sessions on your machine for a branch to explain why changes were made (e.g. logging the working directory before a cd runs). It grew out of a research project tracing students&#39; AI-assisted work, which never gets submitted with the final program (<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=305s" target="_blank" rel="noopener">5:05</a>–<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=408s" target="_blank" rel="noopener">6:48</a>)</li><li><strong>Where the first version still failed:</strong> A research → review → revise loop improved PRs, but revisions brought in errors. One PR claimed tests passed, but the trace showed `bun test` running at the same time as `bunx tsc`, which must run one after the other, so the claim had no evidence behind it. Switching to cheaper writer models made quality worse (<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=501s" target="_blank" rel="noopener">8:21</a>–<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=653s" target="_blank" rel="noopener">10:53</a>)</li></ul><div class="sh">The graph fix</div><ul><li><strong>Relate evidence graph:</strong> Relate is a new open-source embedded graph database written in Rust that runs in memory. It links the why, the code and the checks with their sources into one &quot;neighborhood brief&quot; before writing starts, using local compute and no LLM calls, so agents don&#39;t re-search logs (<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=676s" target="_blank" rel="noopener">11:16</a>–<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=836s" target="_blank" rel="noopener">13:56</a>)</li><li><strong>Strong writer, cheap reviewers:</strong> They keep a Sonnet-class writer but use several Haiku reviewers (or a cheaper Codex model) to check claims against the brief. Cheaper writers turn prose into a mechanical checklist, while cross-checking against the evidence is the mechanical part. The final output said things like &quot;type check plus 71 tests checked on submitted content&quot; (<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=836s" target="_blank" rel="noopener">13:56</a>–<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=970s" target="_blank" rel="noopener">16:10</a>)</li></ul><div class="sh">Results</div><ul><li><strong>PR Bench (their own benchmark):</strong> LLM judges plus human review, using audit traces and code, scored Tracetoon + Relate higher on both Claude and Codex (about 74→76 and 82→86 out of 100), with roughly half the tokens of the earlier version. These are the project&#39;s own comparisons (<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=987s" target="_blank" rel="noopener">16:27</a>–<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=1133s" target="_blank" rel="noopener">18:53</a>)</li><li><strong>General pattern:</strong> Agents are weak at curating data, so build a graph of evidence and relationships up front for any similar task (<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=1133s" target="_blank" rel="noopener">18:53</a>–<a href="https://www.youtube.com/watch?v=gbeuC0ud1p4&amp;t=1170s" target="_blank" rel="noopener">19:30</a>)</li></ul></div></article><article class="it full" id="v-vg3JdjGuJwM" data-title="Every Correction You Give Your Agent Is Data - Brian Douglas, Paper Compute" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=vg3JdjGuJwM" target="_blank" rel="noopener"><img src="'+d+'" srcset="'+Q+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=vg3JdjGuJwM" target="_blank" rel="noopener">Every Correction You Give Your Agent Is Data - Brian Douglas, Paper Compute</a></h3><div class="meta">AI Engineer · Brian Douglas (BDougie), Paper Compute · uploaded 10 Nov, 11:27 PM IST · 12:48</div><div class="verdict v-skim"><b>Verdict:</b> skim from 3:43 — a sensible idea (treat expert corrections as labeled data), but it&#39;s a short demo with no measured results, and the reviewer isn&#39;t released.</div><div class="repeat">🔁 Repeat: &#39;agent observability&#39; — seen 37 times before. New here: labeling captured sessions for the moments an expert pushes back on the agent, and treating those as training data.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 25 times before. New here: turning a teammate&#39;s labeled corrections into a review skill.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 36 times before. New here: a &quot;twin reviewer&quot; that comments on PRs the way one specific teammate would.</div><div class="repeat">🔁 Repeat: &#39;RL fine-tuning small models&#39; — seen 8 times before. New here: SFT/LoRA on a Qwen 4B model using correction traces; DPO needed 70B+ models and rented GPUs.</div><div class="repeat">🔁 Repeat: &#39;training data pipelines&#39; — seen 7 times before. New here: the labeled-correction dataset comes straight from coding-agent session traces.</div><div class="sh">Capturing the missing judgment</div><ul><li><strong>The problem:</strong> He vibe-codes Rust at Paper Compute without really knowing Rust, so he accepts code that compiles and only hears the objections when a teammate (Matt) reviews the PR. Those objections are things like the API structure the team agreed on, or duplicated services. Handing the &quot;reps&quot; to agents also takes them away from juniors (<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=64s" target="_blank" rel="noopener">1:04</a>–<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=107s" target="_blank" rel="noopener">1:47</a>) (<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=295s" target="_blank" rel="noopener">4:55</a>–<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=366s" target="_blank" rel="noopener">6:06</a>)</li><li><strong>Session capture:</strong> Tapes.dev (open source, Apache 2) records agent sessions into a local Postgres database, and the Stereos runtime gives reproducible sandboxes. He uses them for a &quot;Sweeper Agent&quot; that runs up to 10 parallel agents (about 200 on Daytona) on well-defined cleanup work like docs and tests (<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=107s" target="_blank" rel="noopener">1:47</a>–<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=200s" target="_blank" rel="noopener">3:20</a>)</li><li><strong>Labeling pushback:</strong> Paper Console (waitlisted) stores the team&#39;s sessions in one place and tags them. A &quot;pushback&quot; label marks each time an engineer corrects the agent, which signals knowledge the agent lacks (<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=227s" target="_blank" rel="noopener">3:47</a>–<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=328s" target="_blank" rel="noopener">5:28</a>)</li></ul><div class="sh">From traces to a twin reviewer</div><ul><li><strong>Twin Review demo:</strong> A CLI that reviews a PR (#381 in the demo) &quot;as if it was Matt&quot;. It is post-trained on Fireworks using only trace data from Matt&#39;s pushback on Go/Rust code, not GitHub comments. He notes the team now mostly reviews inside the harness, so that feedback never reaches GitHub. He corrects himself: it is not open source, because the data is sensitive (<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=366s" target="_blank" rel="noopener">6:06</a>–<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=486s" target="_blank" rel="noopener">8:06</a>)</li><li><strong>Useful labels:</strong> Pushback, apologies, &quot;golden&quot; sessions and regressions. A common regression is the agent rebuilding Go libraries that already exist, such as mocking libraries (<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=486s" target="_blank" rel="noopener">8:06</a>–<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=535s" target="_blank" rel="noopener">8:55</a>)</li></ul><div class="sh">Practical path</div><ul><li><strong>Skill first, then training:</strong> Turn traces into skills, then skills into evals, then optionally post-train. The team has almost 80,000 sessions to mine. Fine-tuning a Qwen 4B adapter worked fine on a quantized 5090-class GPU, but DPO needed 70B+ models and rented NVIDIA GPUs via Brev. His advice: &quot;write a skill first&quot; (<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=572s" target="_blank" rel="noopener">9:32</a>–<a href="https://www.youtube.com/watch?v=vg3JdjGuJwM&amp;t=734s" target="_blank" rel="noopener">12:14</a>)</li></ul></div></article><article class="it full" id="v-rS36lYuvXQ8" data-title="Your Agent Hates Your CLI - Ayush Bhardwaj, Allos AI" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=rS36lYuvXQ8" target="_blank" rel="noopener"><img src="'+p+'" srcset="'+W+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=rS36lYuvXQ8" target="_blank" rel="noopener">Your Agent Hates Your CLI - Ayush Bhardwaj, Allos AI</a></h3><div class="meta">AI Engineer · Ayush Bhardwaj, Allos AI · uploaded 10 Nov, 11:27 PM IST · 12:20</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — dense, data-backed advice for anyone shipping a CLI or MCP tool to agents, with a method you can run on your own transcripts.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 25 times before. New here: an experiment showing agents follow the skill file literally: 95 of 95 searches kept passing a flag that did nothing until the skill was rewritten.</div><div class="repeat">🔁 Repeat: &#39;agent observability&#39; — seen 37 times before. New here: reading agent transcripts as product analytics for the tool being called, rather than to debug the agent.</div><div class="sh">What agents&#39; pipes reveal</div><ul><li><strong>Workarounds are the bug reports:</strong> Claude Code, Codex and Cursor each piped output through head or tail, guessing where the answer sits. Sanity&#39;s MCP server saw about 3M tool calls from more than 20,000 agents and zero bug reports until it added a feedback tool (<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=15s" target="_blank" rel="noopener">0:15</a>–<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=97s" target="_blank" rel="noopener">1:37</a>)</li><li><strong>Audit of about 20,000 of his own agent calls:</strong> These covered 14 CLIs (git, gh, cargo, curl, npm, docker, and others). About a quarter piped into head, grep, tail, python, sort or wc, rising above half for read-heavy commands (`git show` and `cargo test` 62% each). 83% of pipes matched patterns seen 10 or more times (<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=97s" target="_blank" rel="noopener">1:37</a>–<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=128s" target="_blank" rel="noopener">2:08</a>) (<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=238s" target="_blank" rel="noopener">3:58</a>–<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=272s" target="_blank" rel="noopener">4:32</a>)</li><li><strong>Misleading exit codes:</strong> Without `pipefail`, `cargo test | head` can report success on a compile error. In one Claude Code issue, `tail` cut off a ReferenceError entirely and Claude reported success. Fix: fail loudly, and end output with a short summary and a path to the full log (<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=128s" target="_blank" rel="noopener">2:08</a>–<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=179s" target="_blank" rel="noopener">2:59</a>)</li></ul><div class="sh">Fixes in his chat-history CLI</div><ul><li><strong>The roadmap was in the pipes:</strong> 80% of &quot;open old session&quot; calls were piped. A full session was 1.2M characters, versus about 3,000 around the search match. He added match-context and last-N reads, a compact search mode about 6× smaller than JSON, and multi-session inspect, since a third of inspect calls were hand-written for loops. Infracost made the same move: plain Claude went from 0/6 to 6/6 on hard questions, with 41% lower cost (<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=179s" target="_blank" rel="noopener">2:59</a>–<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=393s" target="_blank" rel="noopener">6:33</a>)</li><li><strong>Docs are the interface:</strong> After he made a flag do nothing, 95 of 95 searches still passed it because the skill said to. Once the skill was rewritten, no session used it. With the new flags taught, the pipe rate fell from 82% to about a quarter, so stale docs are bugs (<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=393s" target="_blank" rel="noopener">6:33</a>–<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=456s" target="_blank" rel="noopener">7:36</a>)</li></ul><div class="sh">Testing and measuring</div><ul><li><strong>Replay tests from transcripts:</strong> Use the commands agents actually ran as test cases, and what they did next as a rough answer key. Replay them on the old and new builds, treat an immediate retry with different arguments as a failing case, and keep some cases back for scoring (<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=456s" target="_blank" rel="noopener">7:36</a>–<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=500s" target="_blank" rel="noopener">8:20</a>)</li><li><strong>Defaults and agent mode:</strong> 55% of pipelines used only head, tail or sed, so ship ranges and limits first. Agents used gh&#39;s list limit flag 81% of the time, but cargo&#39;s quiet mode only about 1 in 10 runs. DuckDB&#39;s agent mode cut output read by 59%, but that was only about 0.5% of total tokens, with no cost or runtime gain, so measure turns and correct answers, not tokens (<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=500s" target="_blank" rel="noopener">8:20</a>–<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=614s" target="_blank" rel="noopener">10:14</a>)</li><li><strong>Don&#39;t let agents design it:</strong> Agents copy poor patterns. One check flagged issues in 97% of real MCP tool descriptions, and an ETH Zurich study found agent-written context files did worse than human ones. Design the tool yourself and let agents check it against real traces. Back up transcripts, because Claude Code can delete inactive ones after 30 days (<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=614s" target="_blank" rel="noopener">10:14</a>–<a href="https://www.youtube.com/watch?v=rS36lYuvXQ8&amp;t=722s" target="_blank" rel="noopener">12:02</a>)</li></ul></div></article><article class="it full" id="v-_NBx2NNOuA4" data-title="Give Your On-Call Its Own AI Teammate - Swaapnika Motapothula, Chinmay Gandhi &amp; Vlad Tsvang, Meta" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=_NBx2NNOuA4" target="_blank" rel="noopener"><img src="'+u+'" srcset="'+K+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=_NBx2NNOuA4" target="_blank" rel="noopener">Give Your On-Call Its Own AI Teammate - Swaapnika Motapothula, Chinmay Gandhi &amp; Vlad Tsvang, Meta</a></h3><div class="meta">AI Engineer · Swaapnika Motapothula, Chinmay Gandhi &amp; Vlad Tsvang, Meta · uploaded 10 Nov, 11:27 PM IST · 15:41</div><div class="verdict v-skim"><b>Verdict:</b> skim from 5:08 — a clear design for an on-call agent (autonomy ladder, team memory, automations), but no measured results yet.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 42 times before. New here: an autonomy ladder built just for on-call, with a clear rule for promotion: an action moves up only when mistakes are cheap, tests, CI or review catch them, and the agent already has a track record on that exact action.</div><div class="repeat">🔁 Repeat: &#39;agent memory&#39; — seen 21 times before. New here: one memory per on-call rotation that scores each entry on whether it helped and promotes or retires entries automatically.</div><div class="repeat">🔁 Repeat: &#39;always-on agents&#39; — seen 11 times before. New here: one agent per rotation with its own identity, plus a scheduled loop that repairs its own stuck or failed runs.</div><div class="repeat">🔁 Repeat: &#39;agent identity&#39; — seen 13 times before. New here: the identity belongs to the rotation, not a person, and gets only the access the team is comfortable granting.</div><div class="repeat">🔁 Repeat: &#39;production incidents&#39; — seen 4 times before. New here: triage that merges related alerts and matches them to past incidents before the engineer wakes up.</div><div class="sh">Why on-call needs a teammate</div><ul><li><strong>Code got faster, on-call didn&#39;t:</strong> About three quarters of new code at Meta is now written with AI, and AI-written changes break production like any other code. The bottleneck moved from writing code to running it (<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=32s" target="_blank" rel="noopener">0:32</a>–<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=79s" target="_blank" rel="noopener">1:19</a>)</li><li><strong>Same 2 a.m. page, two ways:</strong> With 12 alerts firing, today&#39;s assistant only answers when asked. You stay the glue until 2:39. The teammate has already ranked the alerts, folded payments into the checkout issue, diffed the 1:49 config change and matched two past incidents, so you get a hypothesis, a 30-second check and a fix to review (<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=87s" target="_blank" rel="noopener">1:27</a>–<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=193s" target="_blank" rel="noopener">3:13</a>)</li><li><strong>Siloed bots vs one teammate:</strong> The alert script, triage bot, deploy bot and incident history each held one clue, and nothing joined them up. Meta&#39;s answer is one AI teammate per rotation with one loop, a shared team memory, its own identity and a human approval gate. Under the hood it is just a model calling tools in a loop (<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=198s" target="_blank" rel="noopener">3:18</a>–<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=298s" target="_blank" rel="noopener">4:58</a>)</li></ul><div class="sh">Autonomy ladder and the daily flow</div><ul><li><strong>Three levels:</strong> At L1 it investigates and changes nothing. At L2 it drafts the fix with a root cause and test plan, answers review comments and fixes CI, but needs approval. At L3 it handles lower-criticality work on its own. So it can close a noisy alert by itself, while a production mitigation still waits for a human (<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=308s" target="_blank" rel="noopener">5:08</a>–<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=415s" target="_blank" rel="noopener">6:55</a>)</li><li><strong>Smaller decision queue:</strong> In the example, 23 items come in. 18 are handled, 2 are still in progress and 3 need you. A 9 a.m. digest gives one-tap actions (approve a quota bump from your phone). Replying in the thread pulls up evidence: errors began at 8:41, two minutes after a config push cut the payment client timeout. It splits the impact by EU and drafts a rollback for you to approve (<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=435s" target="_blank" rel="noopener">7:15</a>–<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=567s" target="_blank" rel="noopener">9:27</a>)</li><li><strong>Three automations:</strong> (1) Auto-triage sends alerts to the incident investigator, tasks to the team&#39;s own agent and test failures to a coding agent. (2) A scheduled health loop repairs stuck or failed runs and pages a person only if it can&#39;t fix them. (3) Shift-handoff summaries tag the next on-call. Teams can bring their own agents and skills, and every run is logged and can be resumed (<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=571s" target="_blank" rel="noopener">9:31</a>–<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=696s" target="_blank" rel="noopener">11:36</a>)</li></ul><div class="sh">Shared memory and honest results</div><ul><li><strong>Teach once, reuse across shifts:</strong> On Monday Sam tells it to roll back the config first when checkout times out. Three days later Jordan gets that fix, credited to Sam. Entries are scored on whether they helped and promoted or retired automatically, and a correction reopens the item and becomes new memory (<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=704s" target="_blank" rel="noopener">11:44</a>–<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=801s" target="_blank" rel="noopener">13:21</a>)</li><li><strong>No number yet:</strong> They say early signs of a lighter on-call load are promising but won&#39;t give a figure until a proper study is done. Fixes land only through normal review and CI, and most drafts don&#39;t land. Next steps: grade every proposed mitigation, let teams write skills from chat, and earn medium-criticality autonomy (<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=851s" target="_blank" rel="noopener">14:11</a>–<a href="https://www.youtube.com/watch?v=_NBx2NNOuA4&amp;t=932s" target="_blank" rel="noopener">15:32</a>)</li></ul></div></article><article class="it full" id="v-_7P580m4kPY" data-title="You Can&#39;t Tell What an Agent Skill Will Do by Reading It - Roey Ben Chaim, Zenity" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=_7P580m4kPY" target="_blank" rel="noopener"><img src="'+w+'" srcset="'+X+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=_7P580m4kPY" target="_blank" rel="noopener">You Can&#39;t Tell What an Agent Skill Will Do by Reading It - Roey Ben Chaim, Zenity</a></h3><div class="meta">AI Engineer · Roey Ben Chaim, Zenity / MATS · uploaded 10 Nov, 11:27 PM IST · 14:31</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — runs skills instead of reading them and shows concrete findings (about 100 malicious skills, a 1.7M-download credential-stealing campaign).</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 39 times before. New here: judging skills by actually running them in a sandbox (a &quot;detonation chamber&quot;) instead of scanning them, with a real credential-stealing campaign traced end to end.</div><div class="repeat">🔁 Repeat: &#39;sandboxes for agents&#39; — seen 26 times before. New here: the sandbox used as a security lab: a world builder fakes the services a skill expects, and an adversarial operator gets past model refusals.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 25 times before. New here: skills seen as an attack surface: chained installs, fetching prompts from elsewhere, hook abuse, a lookalike skill creator.</div><div class="repeat">🔁 Repeat: &#39;AI supply chain security&#39; — seen 7 times before. New here: about 100 malicious skills found out of thousands and a skill campaign with 1.7M downloads.</div><div class="sh">Why reading the skill is not enough</div><ul><li><strong>Benign can look malicious:</strong> An official Azure diagnostic skill reads cloud and Kubernetes config, contacts the identity service and probes the instance metadata endpoint. That is the same pattern info stealers use, so you have to judge a skill by what it does (<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=51s" target="_blank" rel="noopener">0:51</a>–<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=97s" target="_blank" rel="noopener">1:37</a>)</li><li><strong>Static scans miss things:</strong> SKILL.md is often just the entry point. It can fetch the rest of its prompt from elsewhere or install packages that pull more payloads. LLM analyzers can also be fooled: in Trail of Bits research, a skill with a comment saying the security team approved the change got past one (<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=98s" target="_blank" rel="noopener">1:38</a>–<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=168s" target="_blank" rel="noopener">2:48</a>)</li></ul><div class="sh">Building the detonation chamber</div><ul><li><strong>From sandbox to full harness:</strong> Version 1 (task prompt, agent and skill in a sandbox, then reading traces) wasn&#39;t enough. They added a world builder that supplies the services a skill expects (a Notion skill needs Notion), an operator that tries each path through the skill, and an adversarial operator because agents refused to decode or run payloads (<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=168s" target="_blank" rel="noopener">2:48</a>–<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=359s" target="_blank" rel="noopener">5:59</a>)</li><li><strong>Capture beyond the agent trace:</strong> An npm postinstall script can start a process that reads files and calls out to a server without showing up in the agent&#39;s trace. So they also record process creation, filesystem events and network packets (<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=363s" target="_blank" rel="noopener">6:03</a>–<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li></ul><div class="sh">What they found</div><ul><li><strong>Chained install:</strong> In Zack Korman&#39;s proof of concept, one skill installs a &quot;security review&quot; skill that fetches a SKILL.md from GitHub with hidden instructions, and the agent ran the payload. Running skills this way found about 100 malicious skills out of thousands, which were removed from skills.sh (<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=427s" target="_blank" rel="noopener">7:07</a>–<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=487s" target="_blank" rel="noopener">8:07</a>)</li><li><strong>Lookalike package:</strong> A Polymarket skill&#39;s install script pulls a client package with an extra &quot;s&quot; in its name. Its package.json pointed at an unofficial npm registry, and the payload was an info stealer (<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=490s" target="_blank" rel="noopener">8:10</a>–<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=527s" target="_blank" rel="noopener">8:47</a>)</li><li><strong>Attacker tricks:</strong> Persistence (a line added to the agent&#39;s instructions file saying to reinstall the skill if it&#39;s missing), a fake skill creator that silently uninstalls Anthropic&#39;s official one and installs itself, prompts fetched remotely that can change later or be taken over with the domain, and hooks that fire on every user prompt (<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=529s" target="_blank" rel="noopener">8:49</a>–<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=633s" target="_blank" rel="noopener">10:33</a>)</li><li><strong>Fake Paperclip campaign:</strong> A lookalike org and domain cloned the Paperclip project and added a log action that fetches a payload, decodes it, runs it with node and deletes itself after 60 seconds. The payload collected SSH, AWS and Azure credentials. The PyPI copies came down within about 1–2 hours, but skills using the same command server reached 1.7M downloads before Vercel and Microsoft took them down within 12 hours of the report (<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=635s" target="_blank" rel="noopener">10:35</a>–<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=807s" target="_blank" rel="noopener">13:27</a>)</li><li><strong>Takeaway:</strong> Treat skills like package dependencies: inspect everything they load, give them minimal access and watch what actually runs. Anything that enters the context (sites, database rows, even YouTube comments) is part of the supply chain (<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=813s" target="_blank" rel="noopener">13:33</a>–<a href="https://www.youtube.com/watch?v=_7P580m4kPY&amp;t=866s" target="_blank" rel="noopener">14:26</a>)</li></ul></div></article><article class="it full" id="v-TlOAhw9t5DA" data-title="Merge Is the Bottleneck - Prasanna Sankar, Vorflux" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=TlOAhw9t5DA" target="_blank" rel="noopener"><img src="'+m+'" srcset="'+L+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=TlOAhw9t5DA" target="_blank" rel="noopener">Merge Is the Bottleneck - Prasanna Sankar, Vorflux</a></h3><div class="meta">AI Engineer · Prasanna Sankar, Vorflux (Rippling co-founder) · uploaded 10 Nov, 11:27 PM IST · 20:06</div><div class="verdict v-skim"><b>Verdict:</b> skim from 12:58 — the first half repeats the usual cloud-agent pipeline, the title oversells (merging gets about 30 seconds), and the end is a founder pitch. The Sentry-flood warning and the customer-call example are the useful parts.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 78 times before. New here: Vorflux&#39;s own list of what blocks moving coding agents from the laptop to the cloud (environment, planning, testing, review, merge). Despite the title, merging gets only about 30 seconds.</div><div class="repeat">🔁 Repeat: &#39;always-on agents&#39; — seen 11 times before. New here: &quot;Autobots&quot; that start work on their own from company signals, each with a goal, a home channel and webhooks, plus a ready-made directory of bots.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 24 times before. New here: a manager agent that starts and tracks coding sessions.</div><div class="repeat">🔁 Repeat: &#39;merge queues / CI&#39; — seen 9 times before. New here: only a brief mention of a queue that keeps rebasing PRs and lands them by itself.</div><div class="sh">Vorflux 1.0: removing the laptop</div><ul><li><strong>Background:</strong> Prasanna is a three-time YC founder (Rippling) and Vorflux has raised about $15M. Opus 4.5 let agents work alone for minutes at a time, and contest-winning harnesses spend much more compute at inference time, which led him to build a higher-leverage agent (<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=103s" target="_blank" rel="noopener">1:43</a>–<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=226s" target="_blank" rel="noopener">3:46</a>)</li><li><strong>Full cloud environment:</strong> Subagents set up a raw EC2 instance with your whole stack (ports, secrets, auth, seed data) so cloud agents don&#39;t run &quot;blind&quot; with only one service (<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=226s" target="_blank" rel="noopener">3:46</a>–<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=308s" target="_blank" rel="noopener">5:08</a>)</li><li><strong>Plan, test, review, merge:</strong> Parallel explore subagents write a &quot;plan of plans&quot; with a dependency graph for the subagents. Browser and end-to-end tests run on the machine and come back with a video and a staging link. Several reviewer subagents look from different angles (build with Claude, review with GPT). A merge queue keeps rebasing and lands PRs itself (repeat) (<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=310s" target="_blank" rel="noopener">5:10</a>–<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=526s" target="_blank" rel="noopener">8:46</a>)</li></ul><div class="sh">Vorflux 2.0: Autobots that start work</div><ul><li><strong>The bottleneck moves to project management:</strong> Cloud agents allow 20–30 tasks in parallel versus 3–5 on a desktop, and beyond about 10 it&#39;s hard to keep track. Newer models also lean toward a main agent that orchestrates subagents (<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=637s" target="_blank" rel="noopener">10:37</a>)</li><li><strong>Intent is already in your signals:</strong> To-dos from a customer call or a production alert don&#39;t need a person to kick them off. People keep the creative 0-to-1 work, and the routine follow-ups go to bots (repeat) (<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=656s" target="_blank" rel="noopener">10:56</a>–<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=778s" target="_blank" rel="noopener">12:58</a>)</li><li><strong>Why &quot;fix all Sentry errors&quot; fails:</strong> You get a flood of PRs nobody merges, constant pings, alerts silenced without the root cause and a growing token bill. Instead, treat the bot like a new hire: important things first, frequent check-ins, a budget and visible work (<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=778s" target="_blank" rel="noopener">12:58</a>–<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=857s" target="_blank" rel="noopener">14:17</a>)</li><li><strong>Autobots in practice:</strong> The bot directory includes an on-call bot that triages Sentry and PagerDuty, a CI-speedup bot and a project-manager bot that posts progress and blockers daily. Example: after a beta customer call, a bot read the transcript and screen recording, asked permission, tagged the right engineer, opened a PR, merged and deployed it, and drafted the customer follow-up for approval (<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=857s" target="_blank" rel="noopener">14:17</a>–<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=1016s" target="_blank" rel="noopener">16:56</a>)</li><li><strong>Cost and north star:</strong> Bring your existing Claude Code or Codex subscriptions, or send well-defined work to open models and keep frontier models for judgment. The stated aim is a &quot;zero-employee company&quot;, and he admits Autobots will get things wrong (<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=1040s" target="_blank" rel="noopener">17:20</a>–<a href="https://www.youtube.com/watch?v=TlOAhw9t5DA&amp;t=1107s" target="_blank" rel="noopener">18:27</a>)</li></ul></div></article><article class="it full" id="v-ktbAVYsAxpk" data-title="The Agents Were Fine. Everything Around Them Broke. - Joey Wang, Harvey" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=ktbAVYsAxpk" target="_blank" rel="noopener"><img src="'+g+'" srcset="'+j+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=ktbAVYsAxpk" target="_blank" rel="noopener">The Agents Were Fine. Everything Around Them Broke. - Joey Wang, Harvey</a></h3><div class="meta">AI Engineer · Joey Wang, Harvey · uploaded 10 Nov, 7:30 AM IST · 12:58</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — honest platform failure stories with numbers (900-task alert storm, fair launch queue cutting latency to 70 ms, 60% PR jump breaking merges).</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 78 times before. New here: failure stories from Harvey&#39;s Spectre platform with real numbers: a 900-task alert storm, a 950-task burst from one laptop, a fair launch queue.</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 36 times before. New here: the harness runs whichever agent you like (Cursor, Claude Code, Codex) instead of competing with it.</div><div class="repeat">🔁 Repeat: &#39;always-on agents&#39; — seen 11 times before. New here: scheduled or event-triggered automations that switch themselves off after 5 failures in a row, with budgets or expiry dates.</div><div class="repeat">🔁 Repeat: &#39;merge queues / CI&#39; — seen 9 times before. New here: PRs up about 60% in a month, merges taking over an hour, and the merge queue repeatedly switched off, still unsolved.</div><div class="repeat">🔁 Repeat: &#39;platform engineering&#39; — seen 4 times before. New here: a fair-share scheduler and shared repo copies for an internal agent platform.</div><div class="sh">Spectre: run agents, own what comes after</div><ul><li><strong>Scale:</strong> Last month more than one agent started every minute on Spectre, Harvey&#39;s internal cloud-agent platform. It has produced 10,000 agent-written PRs and about 460 people used it last month, including for data questions and a marketing storyboard (<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=70s" target="_blank" rel="noopener">1:10</a>)</li><li><strong>Don&#39;t compete, run them:</strong> Laptop agents top out at about 5–10. The cloud supplies secrets, the real stack, alerts, one set of rules and capacity. When engineers asked how to get this in Cursor, the answer was &quot;just ask Cursor to use Spectre&quot;, and sessions can move between laptop and cloud (<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=113s" target="_blank" rel="noopener">1:53</a>–<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=207s" target="_blank" rel="noopener">3:27</a>)</li><li><strong>Follow-up loop:</strong> For a 2 a.m. alert, an agent writes the fix, spins up a real copy of the stack and posts proof on the PR. When CI fails it reads the failure and pushes another fix, and once approved it can merge itself. After the loop was turned on for everyone in early October, four of five agent PRs merged into the backend went through it (<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=214s" target="_blank" rel="noopener">3:34</a>–<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=279s" target="_blank" rel="noopener">4:39</a>)</li><li><strong>Callable everything:</strong> The rule became &quot;if a person can click it, an agent can call it.&quot; In May exactly one task came from the terminal all month; by October the CLI was starting about 6,500 tasks a month. Joey had a Claude Code session act as coordinator, splitting his work into 10 milestones and hundreds of sandboxed Spectre tasks (<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=319s" target="_blank" rel="noopener">5:19</a>–<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=431s" target="_blank" rel="noopener">7:11</a>)</li><li><strong>Git was the slow step:</strong> Checking out repos took over a minute per task on average. Fix: keep a copy of every repo on every machine and let each task borrow it (<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=435s" target="_blank" rel="noopener">7:15</a>–<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=456s" target="_blank" rel="noopener">7:36</a>)</li></ul><div class="sh">What broke</div><ul><li><strong>Alert storm (mid-August):</strong> A buggy release fired one alert per workspace, and a workflow tagged the agent on each one. Instead of the usual ~50 tasks, about 900 started in four hours and filled the cluster. Fix: a repeat alert now joins the investigation that&#39;s already open (<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=458s" target="_blank" rel="noopener">7:38</a>–<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=503s" target="_blank" rel="noopener">8:23</a>)</li><li><strong>One laptop, 950 tasks (October):</strong> An engineer launched about 950 tasks from the CLI in about 3 hours and everyone else&#39;s work queued behind them. Within 4 days they shipped a fair launch queue: you get a visible place in line, interactive users go first and everyone gets a fair share. In a 300-task burst test, task-list latency fell from almost 2 seconds to 70 ms (<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=505s" target="_blank" rel="noopener">8:25</a>–<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=570s" target="_blank" rel="noopener">9:30</a>)</li><li><strong>Merge is the new bottleneck:</strong> PRs across the company jumped about 60% in one month, merges that took 15–30 minutes took over an hour, and the merge queue kept being switched off. He says they haven&#39;t solved it (<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=606s" target="_blank" rel="noopener">10:06</a>–<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=645s" target="_blank" rel="noopener">10:45</a>)</li><li><strong>Automation guardrails and lessons:</strong> About 110 people run automations. Each one switches off after 5 failures in a row and can carry a budget or expiry date. Only 1 in 20 merges carries proof that the change works. His advice: own what happens after the code is written, make every action callable, and cap how much an agent, human or alert can start (<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=649s" target="_blank" rel="noopener">10:49</a>–<a href="https://www.youtube.com/watch?v=ktbAVYsAxpk&amp;t=749s" target="_blank" rel="noopener">12:29</a>)</li></ul></div></article></div>',1))])}const se=f(D,[["render",G]]);export{ae as __pageData,se as default};
